/**
 * Helper function to detect if content is BSL code
 */
export function isBSLContent(filePath, content) {
    // Check file extension
    if (filePath.toLowerCase().endsWith('.bsl')) {
        return true;
    }
    // Check content for BSL-specific patterns
    const bslPatterns = [
        /Процедура\s+\w+\s*\(/i,
        /Функция\s+\w+\s*\(/i,
        /КонецПроцедуры/i,
        /КонецФункции/i,
        /НачатьТранзакцию\s*\(\s*\)/i,
        /Запрос\s*=\s*Новый\s+Запрос/i,
    ];
    return bslPatterns.some(pattern => pattern.test(content));
}
